from pathlib import Path
import json,shutil
import pandas as pd
R=Path(__file__).resolve().parents[1];O=R/'outputs';D=R/'deliverables'/'dashboard';D.mkdir(exist_ok=True)
c=pd.read_csv(O/'analysis_cube.csv')
g=c.groupby(['Year','NOC','Sex','Medal']).records.sum().reset_index()
comparison=pd.read_csv(O/'paris2024_rank_sensitivity.csv')
data=json.dumps(g.to_dict('records'),ensure_ascii=False)
ext=json.dumps(comparison.to_dict('records'),ensure_ascii=False)
template='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>百年圣火 谁被看见</title>
<style>body{margin:0;background:#faf9f6;color:#182e35;font:16px/1.7 system-ui,"Microsoft YaHei"}main{max-width:1100px;margin:auto;padding:40px 24px}header{padding:45px 0;border-bottom:1px solid #ccc}h1{font-size:clamp(38px,7vw,76px);line-height:1.2;margin:15px 0;color:#246477}h2{margin-top:50px}p{max-width:850px}label{display:inline-block;margin:8px 16px 8px 0}select,button{font:inherit;padding:8px;border:1px solid #abb;background:white;border-radius:5px}#stats{font-size:22px;padding:20px 0}.row{display:grid;grid-template-columns:55px 1fr 65px;gap:10px;align-items:center;margin:8px 0}.bar{height:22px;background:#246477}.muted{color:#59686b;font-size:14px}table{border-collapse:collapse;width:100%;font-size:14px}td,th{padding:9px;border-bottom:1px solid #ddd;text-align:right}th:first-child,td:first-child{text-align:left}a{color:#246477}img{width:100%;height:auto}section{padding-bottom:24px}footer{margin-top:50px;border-top:1px solid #ccc;padding:24px 0}.tablewrap{overflow:auto}</style>
<main><header><span>1896—2024 · 夏季奥运可视分析</span><h1>百年圣火<br>谁被看见？</h1><p>扩张、女性参与与统计尺度，怎样改变我们理解奥运的方式？从可复现的记录出发，探索排名背后的结构。</p><p class="muted">本地评审版。参赛与奖牌按记录行统计；历史NOC分别保留；主分析排除1906。外部奖牌表待一手核验。</p></header>
<section><h2>01 探索每届竞争格局</h2><label>届次 <select id="year"></select></label><label>性别 <select id="sex"><option value="all">全部</option><option value="F">女性</option><option value="M">男性</option></select></label><label>指标 <select id="metric"><option value="medals">奖牌记录</option><option value="gold">金牌记录</option><option value="all">全部参赛记录</option></select></label><button id="download">导出当前统计CSV</button><div id="stats" aria-live="polite"></div><div id="bars"></div><p class="muted">显示前15代表团；团体成员各占一行。女性奖牌记录不等于女子小项奖牌。筛选后份额的分母也随之变化。记录中的零或缺席不能解释为独立运动员人数。</p></section>
<section><h2>02 同一届，换一种数法</h2><p>统一为仅按金牌数排名、并列取最小名次后，西班牙15→5、荷兰6→3、日本3→9。改变的不只是图上的位置，而是计数所回答的问题。</p><label>比较排序 <select id="order"><option value="gold_only_rank">小项金牌数排名</option><option value="gold_row_rank">金牌记录排名</option></select></label><div class="tablewrap"><table><thead><tr><th>代表团</th><th>小项金牌</th><th>金牌记录</th><th>小项金牌排名</th><th>记录排名</th></tr></thead><tbody id="comparison"></tbody></table></div><p class="muted">固定2024年，与上方筛选独立。15个显式映射代表团，排名在各自完整榜计算；排除AIN。外部小项计数来自<a href="https://en.wikipedia.org/wiki/2024_Summer_Olympics_medal_table">维基百科快照</a>，不是由泛化Event去重还原。</p></section>
<section><h2>03 她的奥运</h2><img src="C_female_records.png" alt="1896至2024女性参赛记录占比曲线，2024达到49.10%"><p>49.10%是女性参赛记录占比。由于同一人可能参加多个小项，它不能直接当成女性运动员人数占比。</p></section>
<section><h2>04 主场提升并非必然</h2><img src="S1_host_windows.png" alt="九个东道主案例前后届奖牌记录份额"><p>九个案例中八个主办届份额上升，巴西2016年反而下降；英国2012年后继续增长。选择样本及同期比较只能说明关联，不能证明因果。</p></section>
<footer><strong>先声明在数什么，再解释谁领先。</strong><p class="muted">数据：Kaggle Summer Olympics Medals (1896–2024)，Stefany De Oliveira；上游Nitish Sharma及Petro Ivaniuk。衍生数据CC BY-NC-SA 4.0。原始CSV不随提交包分发。项目映射、质量检查、特殊记录与来源快照见配套代码及报告。</p></footer></main>
<script>const data=__DATA__, ext=__EXT__;const $=s=>document.getElementById(s);const years=[...new Set(data.map(r=>r.Year))].sort((a,b)=>a-b);$('year').innerHTML=years.map(y=>`<option>${y}</option>`).join('');$('year').value=2024;let current=[];
function render(){const y=+$('year').value,s=$('sex').value,m=$('metric').value;const rows=data.filter(r=>r.Year===y&&(s==='all'||r.Sex===s)&&(m==='all'||m==='gold'&&r.Medal==='Gold'||m==='medals'&&r.Medal!=='No medal'));const sums={};rows.forEach(r=>sums[r.NOC]=(sums[r.NOC]||0)+r.records);current=Object.entries(sums).sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0]));const total=current.reduce((a,r)=>a+r[1],0);$('stats').textContent=`${y} · 当前筛选共 ${total.toLocaleString()} 条记录 · ${current.length} 个有记录的代表团`;$('bars').innerHTML=current.slice(0,15).map(([n,v])=>`<div class="row"><strong>${n}</strong><div><div class="bar" style="width:${v/current[0][1]*100}%"></div></div><span>${v}</span></div>`).join('')||'无符合条件的记录';}
function compare(){const k=$('order').value;$('comparison').innerHTML=[...ext].sort((a,b)=>a[k]-b[k]||a.NOC.localeCompare(b.NOC)).map(r=>`<tr><td>${r.NOC}</td><td>${r.gold}</td><td>${r.gold_rows}</td><td>${r.gold_only_rank}</td><td>${r.gold_row_rank}</td></tr>`).join('');}['year','sex','metric'].forEach(id=>$(id).onchange=render);$('order').onchange=compare;$('download').onclick=()=>{const b=new Blob(['NOC,records\\n'+current.map(r=>r.join(',')).join('\\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=`olympics_${$('year').value}_${$('sex').value}_${$('metric').value}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};render();compare();</script></html>'''
(D/'index.html').write_text(template.replace('__DATA__',data).replace('__EXT__',ext),encoding='utf-8')
for n in ['C_female_records','S1_host_windows']:shutil.copy2(O/'figures'/f'{n}.png',D/f'{n}.png')
print(f'Dashboard: {D}; {len(g)} aggregated rows')
